//! Board snapshot types for JavaScript serialization.
//!
//! These types provide a flat, serializable view of the board state
//! suitable for transmission to JavaScript via serde-wasm-bindgen.
//!
//! All types use primitive types (i64, i32, u32, String) that serialize
//! cleanly to JavaScript numbers and strings.

use cypcb_drc::DrcViolation;
use serde::{Deserialize, Serialize};

/// Complete snapshot of the board state for rendering.
///
/// This is the main type returned by `PcbEngine::get_snapshot()`.
/// It contains all information needed to render the board in JavaScript.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardSnapshot {
    /// Board information (if a board has been defined).
    pub board: Option<BoardInfo>,
    /// All components on the board.
    pub components: Vec<ComponentInfo>,
    /// All nets and their connections.
    pub nets: Vec<NetInfo>,
    /// DRC violations found after loading.
    pub violations: Vec<ViolationInfo>,
    /// Copper traces (routed connections).
    pub traces: Vec<TraceInfo>,
    /// Vias (layer-to-layer connections).
    pub vias: Vec<ViaInfo>,
    /// Ratsnest lines (unrouted connections).
    pub ratsnest: Vec<RatsnestInfo>,
}

/// A DRC violation for display in the viewer.
///
/// This is a simplified representation of `cypcb_drc::DrcViolation`
/// suitable for JavaScript serialization and rendering.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViolationInfo {
    /// Violation type (clearance, drill_size, unconnected_pin, etc.)
    pub kind: String,
    /// Board location X in nanometers.
    pub x_nm: i64,
    /// Board location Y in nanometers.
    pub y_nm: i64,
    /// Human-readable message.
    pub message: String,
}

impl ViolationInfo {
    /// Create a ViolationInfo from a DrcViolation.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::{DrcViolation, ViolationKind};
    /// use cypcb_core::Point;
    /// use cypcb_world::Entity;
    /// use cypcb_render::ViolationInfo;
    ///
    /// let v = DrcViolation::unconnected_pin(
    ///     Entity::from_raw(1),
    ///     "1",
    ///     "R1",
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// let info = ViolationInfo::from_drc(&v);
    /// assert_eq!(info.kind, "unconnected-pin");
    /// assert!(info.message.contains("R1.1"));
    /// ```
    pub fn from_drc(v: &DrcViolation) -> Self {
        ViolationInfo {
            kind: format!("{}", v.kind),
            x_nm: v.location.x.0,
            y_nm: v.location.y.0,
            message: v.message.clone(),
        }
    }
}

/// Board-level information.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardInfo {
    /// Board name/identifier.
    pub name: String,
    /// Board width in nanometers.
    pub width_nm: i64,
    /// Board height in nanometers.
    pub height_nm: i64,
    /// Number of copper layers.
    pub layer_count: u8,
}

/// Component information for rendering.
#[derive(Debug, Serialize, Deserialize)]
pub struct ComponentInfo {
    /// Reference designator (R1, C1, U1, etc.).
    pub refdes: String,
    /// Component value (10k, 100nF, etc.).
    pub value: String,
    /// X position in nanometers.
    pub x_nm: i64,
    /// Y position in nanometers.
    pub y_nm: i64,
    /// Rotation in millidegrees (0-359999).
    pub rotation_mdeg: i32,
    /// Footprint name/identifier.
    pub footprint: String,
    /// Pad definitions from the footprint.
    pub pads: Vec<PadInfo>,
}

/// Pad information for rendering.
///
/// Positions are relative to the component origin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PadInfo {
    /// Pad number/name (e.g., "1", "2", "A1", "VCC").
    pub number: String,
    /// X position relative to component origin, in nanometers.
    pub x_nm: i64,
    /// Y position relative to component origin, in nanometers.
    pub y_nm: i64,
    /// Pad width in nanometers.
    pub width_nm: i64,
    /// Pad height in nanometers.
    pub height_nm: i64,
    /// Shape as string: "circle", "rect", "roundrect", "oblong".
    pub shape: String,
    /// Copper layer bit mask (bit 0 = top, bit 1 = bottom, bits 2-31 = inner).
    pub layer_mask: u32,
    /// Drill diameter in nanometers (None for SMD pads).
    pub drill_nm: Option<i64>,
}

/// Net information.
#[derive(Debug, Serialize, Deserialize)]
pub struct NetInfo {
    /// Net name.
    pub name: String,
    /// Net ID (internal identifier).
    pub id: u32,
    /// All pin connections to this net.
    pub connections: Vec<PinRef>,
}

/// Reference to a component pin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PinRef {
    /// Component reference designator.
    pub component: String,
    /// Pin number/name.
    pub pin: String,
}

/// A single segment of a trace (line from start to end).
///
/// TraceSegmentInfo is the JavaScript-serializable version of
/// `cypcb_world::components::trace::TraceSegment`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceSegmentInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
}

/// Trace information for rendering.
///
/// Represents a copper trace as a polyline with a given width.
/// Used by the JavaScript renderer to draw routed connections.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceInfo {
    /// Entity index for selection/hit-testing. Maps back to the ECS entity.
    pub id: u32,
    /// The polyline path as a vector of segments.
    pub segments: Vec<TraceSegmentInfo>,
    /// Trace width in nanometers.
    pub width: f64,
    /// Layer name ("Top" or "Bottom").
    pub layer: String,
    /// Net name this trace belongs to.
    pub net_name: String,
    /// Whether this trace is locked (manual, not to be modified).
    pub locked: bool,
}

/// Via information for rendering.
///
/// Represents a plated through-hole connecting copper layers.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViaInfo {
    /// Entity index for selection/hit-testing. Maps back to the ECS entity.
    pub id: u32,
    /// Center X coordinate in nanometers.
    pub x: f64,
    /// Center Y coordinate in nanometers.
    pub y: f64,
    /// Drill hole diameter in nanometers.
    pub drill: f64,
    /// Outer diameter (copper ring) in nanometers.
    pub outer_diameter: f64,
    /// Net name this via belongs to.
    pub net_name: String,
}

/// Ratsnest line information for rendering.
///
/// Represents an unrouted connection between two pins.
/// Shown as a thin line to indicate what still needs routing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RatsnestInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
    /// Net name this connection belongs to.
    pub net_name: String,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_board_snapshot_serializes() {
        let snapshot = BoardSnapshot {
            board: Some(BoardInfo {
                name: "Test".to_string(),
                width_nm: 100_000_000,
                height_nm: 80_000_000,
                layer_count: 2,
            }),
            components: vec![ComponentInfo {
                refdes: "R1".to_string(),
                value: "10k".to_string(),
                x_nm: 10_000_000,
                y_nm: 20_000_000,
                rotation_mdeg: 0,
                footprint: "0402".to_string(),
                pads: vec![
                    PadInfo {
                        number: "1".to_string(),
                        x_nm: -500_000,
                        y_nm: 0,
                        width_nm: 600_000,
                        height_nm: 500_000,
                        shape: "rect".to_string(),
                        layer_mask: 1,
                        drill_nm: None,
                    },
                    PadInfo {
                        number: "2".to_string(),
                        x_nm: 500_000,
                        y_nm: 0,
                        width_nm: 600_000,
                        height_nm: 500_000,
                        shape: "rect".to_string(),
                        layer_mask: 1,
                        drill_nm: None,
                    },
                ],
            }],
            nets: vec![NetInfo {
                name: "VCC".to_string(),
                id: 0,
                connections: vec![PinRef {
                    component: "R1".to_string(),
                    pin: "1".to_string(),
                }],
            }],
            violations: vec![],
            traces: vec![],
            vias: vec![],
            ratsnest: vec![],
        };

        // Verify it can serialize to JSON (serde-wasm-bindgen uses serde)
        let json = serde_json::to_string(&snapshot).unwrap();
        assert!(json.contains("\"name\":\"Test\""));
        assert!(json.contains("\"refdes\":\"R1\""));
        assert!(json.contains("\"name\":\"VCC\""));
        assert!(json.contains("\"violations\":[]"));
        assert!(json.contains("\"traces\":[]"));
        assert!(json.contains("\"vias\":[]"));
        assert!(json.contains("\"ratsnest\":[]"));
    }

    #[test]
    fn test_violation_info_from_drc() {
        use cypcb_core::Point;
        use cypcb_world::Entity;

        let violation = cypcb_drc::DrcViolation::unconnected_pin(
            Entity::from_raw(1),
            "1",
            "R1",
            Point::from_mm(10.0, 20.0),
        );
        let info = ViolationInfo::from_drc(&violation);

        assert_eq!(info.kind, "unconnected-pin");
        assert_eq!(info.x_nm, 10_000_000);
        assert_eq!(info.y_nm, 20_000_000);
        assert!(info.message.contains("R1.1"));
    }

    #[test]
    fn test_violation_info_serializes() {
        let violation = ViolationInfo {
            kind: "clearance".to_string(),
            x_nm: 5_000_000,
            y_nm: 10_000_000,
            message: "Clearance violation: 0.10mm actual, 0.15mm required".to_string(),
        };

        let json = serde_json::to_string(&violation).unwrap();
        assert!(json.contains("\"kind\":\"clearance\""));
        assert!(json.contains("\"x_nm\":5000000"));
        assert!(json.contains("\"message\""));
    }

    #[test]
    fn test_trace_info_serializes() {
        let trace = TraceInfo {
            id: 0,
            segments: vec![
                TraceSegmentInfo {
                    start_x: 0.0,
                    start_y: 0.0,
                    end_x: 10_000_000.0,
                    end_y: 0.0,
                },
                TraceSegmentInfo {
                    start_x: 10_000_000.0,
                    start_y: 0.0,
                    end_x: 10_000_000.0,
                    end_y: 5_000_000.0,
                },
            ],
            width: 200_000.0, // 0.2mm
            layer: "Top".to_string(),
            net_name: "VCC".to_string(),
            locked: true,
        };

        let json = serde_json::to_string(&trace).unwrap();
        assert!(json.contains("\"layer\":\"Top\""));
        assert!(json.contains("\"net_name\":\"VCC\""));
        assert!(json.contains("\"locked\":true"));
        assert!(json.contains("\"width\":200000"));
        assert!(json.contains("\"segments\""));
    }

    #[test]
    fn test_via_info_serializes() {
        let via = ViaInfo {
            id: 0,
            x: 5_000_000.0,
            y: 10_000_000.0,
            drill: 300_000.0,       // 0.3mm
            outer_diameter: 600_000.0, // 0.6mm
            net_name: "GND".to_string(),
        };

        let json = serde_json::to_string(&via).unwrap();
        assert!(json.contains("\"x\":5000000"));
        assert!(json.contains("\"y\":10000000"));
        assert!(json.contains("\"drill\":300000"));
        assert!(json.contains("\"outer_diameter\":600000"));
        assert!(json.contains("\"net_name\":\"GND\""));
    }

    #[test]
    fn test_ratsnest_info_serializes() {
        let ratsnest = RatsnestInfo {
            start_x: 0.0,
            start_y: 0.0,
            end_x: 20_000_000.0,
            end_y: 15_000_000.0,
            net_name: "SIGNAL".to_string(),
        };

        let json = serde_json::to_string(&ratsnest).unwrap();
        assert!(json.contains("\"start_x\":0"));
        assert!(json.contains("\"start_y\":0"));
        assert!(json.contains("\"end_x\":20000000"));
        assert!(json.contains("\"end_y\":15000000"));
        assert!(json.contains("\"net_name\":\"SIGNAL\""));
    }

    #[test]
    fn test_snapshot_with_traces() {
        let snapshot = BoardSnapshot {
            board: Some(BoardInfo {
                name: "TraceTest".to_string(),
                width_nm: 50_000_000,
                height_nm: 30_000_000,
                layer_count: 2,
            }),
            components: vec![],
            nets: vec![],
            violations: vec![],
            traces: vec![TraceInfo {
                id: 1,
                segments: vec![TraceSegmentInfo {
                    start_x: 5_000_000.0,
                    start_y: 5_000_000.0,
                    end_x: 25_000_000.0,
                    end_y: 5_000_000.0,
                }],
                width: 250_000.0,
                layer: "Top".to_string(),
                net_name: "VCC".to_string(),
                locked: false,
            }],
            vias: vec![ViaInfo {
                id: 2,
                x: 25_000_000.0,
                y: 5_000_000.0,
                drill: 300_000.0,
                outer_diameter: 600_000.0,
                net_name: "VCC".to_string(),
            }],
            ratsnest: vec![],
        };

        let json = serde_json::to_string(&snapshot).unwrap();
        assert!(json.contains("\"traces\""));
        assert!(json.contains("\"vias\""));
        assert!(json.contains("\"VCC\""));
    }
}

/**
 * TypeScript interfaces matching Rust BoardSnapshot
 * These types will be used when receiving data from the WASM module
 */

export interface BoardSnapshot {
  board: BoardInfo | null;
  components: ComponentInfo[];
  nets: NetInfo[];
  violations: ViolationInfo[];
  traces: TraceInfo[];
  vias: ViaInfo[];
  ratsnest: RatsnestInfo[];
}

/**
 * A DRC violation for display in the viewer
 */
export interface ViolationInfo {
  /** Violation type: clearance, drill-size, unconnected-pin, etc. */
  kind: string;
  /** X location in nanometers */
  x_nm: number;
  /** Y location in nanometers */
  y_nm: number;
  /** Human-readable message */
  message: string;
}

export interface BoardInfo {
  name: string;
  width_nm: number;
  height_nm: number;
  layer_count: number;
}

export interface ComponentInfo {
  refdes: string;
  value: string;
  x_nm: number;
  y_nm: number;
  rotation_mdeg: number;
  footprint: string;
  pads: PadInfo[];
}

export interface PadInfo {
  number: string;
  x_nm: number;
  y_nm: number;
  width_nm: number;
  height_nm: number;
  shape: string;
  layer_mask: number;
  drill_nm: number | null;
}

export interface NetInfo {
  name: string;
  id: number;
  connections: PinRef[];
}

export interface PinRef {
  component: string;
  pin: string;
}

/**
 * A single segment of a trace (line from start to end)
 */
export interface TraceSegmentInfo {
  start_x: number;
  start_y: number;
  end_x: number;
  end_y: number;
}

/**
 * Trace information for rendering
 */
export interface TraceInfo {
  /** Entity index for selection/hit-testing */
  id: number;
  segments: TraceSegmentInfo[];
  width: number;
  layer: string;
  net_name: string;
  locked: boolean;
}

/**
 * Via information for rendering
 */
export interface ViaInfo {
  /** Entity index for selection/hit-testing */
  id: number;
  x: number;
  y: number;
  drill: number;
  outer_diameter: number;
  net_name: string;
}

/**
 * Ratsnest line for unrouted connections
 */
export interface RatsnestInfo {
  start_x: number;
  start_y: number;
  end_x: number;
  end_y: number;
  net_name: string;
}

/**
 * 3D PCB Board Renderer
 *
 * Renders the PCB board as a 3D scene with Three.js.
 * Coordinate system: X/Y from board data (mm), Z is stack-up axis (Z-up).
 * Board bottom face at Z=0, top face at Z=1.6mm.
 *
 * Copper layers:
 *   Bottom copper: Z = 0.035 mm (copper thickness above board bottom)
 *   Top copper:    Z = 1.565 mm (board thickness minus copper thickness)
 *   Pads get slight Z-offset above traces to prevent Z-fighting.
 */

import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import type { BoardSnapshot, TraceInfo, ViaInfo, ComponentInfo } from './types';
import { LAYER_COLORS, LAYER_MASK, type LayerVisibility } from './layers';

/** Standard PCB thickness in mm */
const BOARD_THICKNESS_MM = 1.6;

/** Copper layer thickness in mm */
const COPPER_THICKNESS_MM = 0.035;

/** Z-heights for copper layers (center of copper slab) */
const Z_BOTTOM_COPPER = COPPER_THICKNESS_MM; // 0.035 mm
const Z_TOP_COPPER = BOARD_THICKNESS_MM - COPPER_THICKNESS_MM; // 1.565 mm

/** Pad Z-offsets slightly above traces to avoid Z-fighting */
const Z_BOTTOM_PAD = Z_BOTTOM_COPPER + 0.005; // 0.04 mm
const Z_TOP_PAD = Z_TOP_COPPER + 0.005; // 1.57 mm

/** Nanometers to millimeters conversion factor */
const NM_TO_MM = 1e-6;

/** PCB substrate green material color */
const PCB_GREEN = 0x1a7a3a;

/** PCB substrate roughness for physical material */
const PCB_ROUGHNESS = 0.7;

/** Parse a CSS hex color string to a Three.js Color */
function hexToColor(hex: string): THREE.Color {
  return new THREE.Color(hex);
}

export class Renderer3D {
  private renderer: THREE.WebGLRenderer | null = null;
  private scene: THREE.Scene | null = null;
  private camera: THREE.PerspectiveCamera | null = null;
  private controls: OrbitControls | null = null;
  private container: HTMLElement | null = null;
  private animFrameId: number | null = null;
  private active = false;
  private boardGroup: THREE.Group | null = null;

  /** Named layer groups for visibility toggling */
  private layerGroups: Map<string, THREE.Group> = new Map();

  /**
   * Initialize the 3D renderer inside the given container element.
   * Creates WebGL renderer, scene, camera, controls, and lighting.
   */
  init(container: HTMLElement): void {
    this.container = container;

    // Create WebGL renderer
    try {
      this.renderer = new THREE.WebGLRenderer({
        antialias: true,
        alpha: false,
      });
    } catch (e) {
      console.error('[3D] WebGL not available', e);
      throw new Error('WebGL not available');
    }

    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(container.clientWidth, container.clientHeight);
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;
    this.renderer.domElement.style.position = 'absolute';
    this.renderer.domElement.style.top = '0';
    this.renderer.domElement.style.left = '0';
    this.renderer.domElement.id = 'three-canvas';
    container.appendChild(this.renderer.domElement);

    // Scene
    this.scene = new THREE.Scene();
    this.setBackgroundFromCSS();

    // Camera — perspective, looking down at board
    const aspect = container.clientWidth / container.clientHeight;
    this.camera = new THREE.PerspectiveCamera(45, aspect, 0.1, 10000);
    this.camera.position.set(0, 0, 100);
    this.camera.up.set(0, 1, 0);

    // OrbitControls
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.1;
    this.controls.target.set(0, 0, 0);
    this.controls.update();

    // Lighting — ambient + directional for even illumination
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    this.scene.add(ambientLight);

    const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight1.position.set(50, 80, 100);
    this.scene.add(dirLight1);

    const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
    dirLight2.position.set(-30, -50, 60);
    this.scene.add(dirLight2);

    // Board group for easy clearing
    this.boardGroup = new THREE.Group();
    this.scene.add(this.boardGroup);

    // Resize handler
    this.onResize = this.onResize.bind(this);
    window.addEventListener('resize', this.onResize);

    // Start animation loop
    this.active = true;
    this.animate();

    // Expose debug surface
    this.updateDebugSurface();

    console.log('[3D] Initialized');
  }

  /**
   * Update board geometry from a BoardSnapshot.
   * Builds: substrate slab, copper traces, pads, vias, with layer groups for visibility.
   */
  updateBoard(snapshot: BoardSnapshot, layers: LayerVisibility): void {
    if (!this.boardGroup || !this.scene) return;

    // Clear existing board geometry and layer groups
    this.clearBoardGroup();
    this.layerGroups.clear();

    if (!snapshot.board) {
      console.log('[3D] No board data');
      this.updateDebugSurface();
      return;
    }

    const widthMm = snapshot.board.width_nm * NM_TO_MM;
    const heightMm = snapshot.board.height_nm * NM_TO_MM;

    // Board substrate — box geometry centered on X/Y, bottom at Z=0
    const subGeo = new THREE.BoxGeometry(widthMm, heightMm, BOARD_THICKNESS_MM);
    subGeo.translate(widthMm / 2, heightMm / 2, BOARD_THICKNESS_MM / 2);

    const subMat = new THREE.MeshPhysicalMaterial({
      color: PCB_GREEN,
      roughness: PCB_ROUGHNESS,
      metalness: 0.05,
      clearcoat: 0.3,
      clearcoatRoughness: 0.4,
    });

    const boardMesh = new THREE.Mesh(subGeo, subMat);
    boardMesh.name = 'board-substrate';
    this.boardGroup.add(boardMesh);

    // Create layer groups
    const topGroup = new THREE.Group();
    topGroup.name = 'layer-top';
    const bottomGroup = new THREE.Group();
    bottomGroup.name = 'layer-bottom';
    const viaGroup = new THREE.Group();
    viaGroup.name = 'layer-vias';

    this.boardGroup.add(topGroup);
    this.boardGroup.add(bottomGroup);
    this.boardGroup.add(viaGroup);

    this.layerGroups.set('topCopper', topGroup);
    this.layerGroups.set('bottomCopper', bottomGroup);
    this.layerGroups.set('vias', viaGroup);

    // Build copper geometry
    this.buildTraces(snapshot.traces || [], topGroup, bottomGroup);
    this.buildPads(snapshot.components || [], topGroup, bottomGroup);
    this.buildVias(snapshot.vias || [], viaGroup);

    // Apply initial layer visibility
    this.updateLayerVisibility(layers);

    // Set orbit target to board center
    if (this.controls && this.camera) {
      const cx = widthMm / 2;
      const cy = heightMm / 2;
      const cz = BOARD_THICKNESS_MM / 2;
      this.controls.target.set(cx, cy, cz);

      const maxDim = Math.max(widthMm, heightMm);
      const distance = maxDim * 1.5;
      this.camera.position.set(cx, cy - distance * 0.3, distance);
      this.controls.update();
    }

    const componentCount = snapshot.components?.length ?? 0;
    console.log(`[3D] Board updated: ${widthMm.toFixed(1)}x${heightMm.toFixed(1)} mm, ${componentCount} components`);
    this.updateDebugSurface();
  }

  /**
   * Update visibility of layer groups based on checkbox state.
   * Called from main.ts layer checkbox handlers.
   */
  updateLayerVisibility(layers: LayerVisibility): void {
    const topGroup = this.layerGroups.get('topCopper');
    const bottomGroup = this.layerGroups.get('bottomCopper');
    const viaGroup = this.layerGroups.get('vias');

    if (topGroup) topGroup.visible = layers.topCopper;
    if (bottomGroup) bottomGroup.visible = layers.bottomCopper;
    // Vias visible when either copper layer is visible
    if (viaGroup) viaGroup.visible = layers.topCopper || layers.bottomCopper;
  }

  /**
   * Dispose all Three.js resources and remove DOM elements.
   */
  dispose(): void {
    this.active = false;

    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }

    window.removeEventListener('resize', this.onResize);

    // Dispose board group contents
    this.clearBoardGroup();

    // Dispose controls
    if (this.controls) {
      this.controls.dispose();
      this.controls = null;
    }

    // Dispose scene children (lights, etc.)
    if (this.scene) {
      this.scene.traverse((obj) => {
        if (obj instanceof THREE.Mesh) {
          obj.geometry?.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach(m => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
      this.scene.clear();
      this.scene = null;
    }

    // Remove renderer DOM element
    if (this.renderer) {
      if (this.renderer.domElement.parentElement) {
        this.renderer.domElement.parentElement.removeChild(this.renderer.domElement);
      }
      this.renderer.dispose();
      this.renderer = null;
    }

    this.camera = null;
    this.boardGroup = null;
    this.container = null;
    this.layerGroups.clear();

    // Update debug surface
    this.updateDebugSurface();

    console.log('[3D] Disposed');
  }

  /**
   * Update the scene background color from a CSS color string.
   */
  setBackground(color: string): void {
    if (this.scene) {
      this.scene.background = new THREE.Color(color);
    }
  }

  /**
   * Whether the renderer is currently active and running.
   */
  get isActive(): boolean {
    return this.active;
  }

  // -- Copper geometry builders --

  /**
   * Build merged trace geometry per layer.
   * Each trace segment → flat quad (4 verts, 2 tris) at the correct Z-height.
   * All segments on a layer are merged into one BufferGeometry for draw-call efficiency.
   */
  private buildTraces(traces: TraceInfo[], topGroup: THREE.Group, bottomGroup: THREE.Group): void {
    // Bucket segments by layer
    const topPositions: number[] = [];
    const bottomPositions: number[] = [];

    let topSegCount = 0;
    let bottomSegCount = 0;

    for (const trace of traces) {
      const widthMm = trace.width * NM_TO_MM;
      const halfW = widthMm / 2;
      const isTop = trace.layer === 'Top';
      const zHeight = isTop ? Z_TOP_COPPER : Z_BOTTOM_COPPER;
      const positions = isTop ? topPositions : bottomPositions;

      for (const seg of trace.segments) {
        const sx = seg.start_x * NM_TO_MM;
        const sy = seg.start_y * NM_TO_MM;
        const ex = seg.end_x * NM_TO_MM;
        const ey = seg.end_y * NM_TO_MM;

        // Direction vector and perpendicular for width
        const dx = ex - sx;
        const dy = ey - sy;
        const len = Math.sqrt(dx * dx + dy * dy);
        if (len < 1e-6) continue; // skip zero-length segments

        // Perpendicular (normalized) scaled by half-width
        const px = (-dy / len) * halfW;
        const py = (dx / len) * halfW;

        // Quad corners: start-left, start-right, end-right, end-left
        const slx = sx + px, sly = sy + py;
        const srx = sx - px, sry = sy - py;
        const erx = ex - px, ery = ey - py;
        const elx = ex + px, ely = ey + py;

        // Triangle 1: SL, SR, ER
        positions.push(slx, sly, zHeight);
        positions.push(srx, sry, zHeight);
        positions.push(erx, ery, zHeight);

        // Triangle 2: SL, ER, EL
        positions.push(slx, sly, zHeight);
        positions.push(erx, ery, zHeight);
        positions.push(elx, ely, zHeight);

        if (isTop) topSegCount++;
        else bottomSegCount++;
      }
    }

    // Create top copper trace mesh
    if (topPositions.length > 0) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(topPositions, 3));
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({
        color: hexToColor(LAYER_COLORS.top_copper),
        metalness: 0.6,
        roughness: 0.3,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = 'traces-top';
      topGroup.add(mesh);
    }

    // Create bottom copper trace mesh
    if (bottomPositions.length > 0) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(bottomPositions, 3));
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({
        color: hexToColor(LAYER_COLORS.bottom_copper),
        metalness: 0.6,
        roughness: 0.3,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = 'traces-bottom';
      bottomGroup.add(mesh);
    }

    if (topSegCount > 0) console.log(`[3D] Built ${topSegCount} trace segments on layer Top`);
    else console.log('[3D] Warning: 0 traces on layer Top');
    if (bottomSegCount > 0) console.log(`[3D] Built ${bottomSegCount} trace segments on layer Bottom`);
    else console.log('[3D] Warning: 0 traces on layer Bottom');
  }

  /**
   * Build pad geometry from components.
   * Pads are merged into per-layer BufferGeometry. Through-hole pads go in both groups.
   */
  private buildPads(components: ComponentInfo[], topGroup: THREE.Group, bottomGroup: THREE.Group): void {
    const topPositions: number[] = [];
    const bottomPositions: number[] = [];
    let padCount = 0;

    for (const comp of components) {
      const compXmm = comp.x_nm * NM_TO_MM;
      const compYmm = comp.y_nm * NM_TO_MM;
      const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);
      const cosR = Math.cos(radians);
      const sinR = Math.sin(radians);

      for (const pad of comp.pads) {
        // Rotate pad offset by component rotation
        const padXmm = pad.x_nm * NM_TO_MM;
        const padYmm = pad.y_nm * NM_TO_MM;
        const rotX = padXmm * cosR - padYmm * sinR;
        const rotY = padXmm * sinR + padYmm * cosR;

        const worldX = compXmm + rotX;
        const worldY = compYmm + rotY;
        const wMm = pad.width_nm * NM_TO_MM;
        const hMm = pad.height_nm * NM_TO_MM;

        const isTop = (pad.layer_mask & LAYER_MASK.TOP_COPPER) !== 0;
        const isBottom = (pad.layer_mask & LAYER_MASK.BOTTOM_COPPER) !== 0;

        // Build pad shape as triangles based on pad.shape
        const padTris = this.buildPadTriangles(worldX, worldY, wMm, hMm, radians, pad.shape);

        if (isTop) {
          for (const tri of padTris) {
            topPositions.push(tri[0], tri[1], Z_TOP_PAD);
            topPositions.push(tri[2], tri[3], Z_TOP_PAD);
            topPositions.push(tri[4], tri[5], Z_TOP_PAD);
          }
        }
        if (isBottom) {
          for (const tri of padTris) {
            bottomPositions.push(tri[0], tri[1], Z_BOTTOM_PAD);
            bottomPositions.push(tri[2], tri[3], Z_BOTTOM_PAD);
            bottomPositions.push(tri[4], tri[5], Z_BOTTOM_PAD);
          }
        }

        padCount++;
      }
    }

    // Create pad meshes
    if (topPositions.length > 0) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(topPositions, 3));
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({
        color: hexToColor(LAYER_COLORS.top_copper),
        metalness: 0.6,
        roughness: 0.3,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = 'pads-top';
      topGroup.add(mesh);
    }

    if (bottomPositions.length > 0) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(bottomPositions, 3));
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({
        color: hexToColor(LAYER_COLORS.bottom_copper),
        metalness: 0.6,
        roughness: 0.3,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = 'pads-bottom';
      bottomGroup.add(mesh);
    }

    console.log(`[3D] Built ${padCount} pads`);
  }

  /**
   * Build triangles for a single pad shape at the given world position.
   * Returns array of [x0,y0, x1,y1, x2,y2] triangles.
   */
  private buildPadTriangles(
    cx: number, cy: number,
    w: number, h: number,
    rotation: number,
    shape: string,
  ): number[][] {
    const cosR = Math.cos(rotation);
    const sinR = Math.sin(rotation);

    // Helper to rotate a point around (cx, cy)
    const rot = (lx: number, ly: number): [number, number] => {
      const rx = lx * cosR - ly * sinR;
      const ry = lx * sinR + ly * cosR;
      return [cx + rx, cy + ry];
    };

    const hw = w / 2;
    const hh = h / 2;

    switch (shape) {
      case 'circle': {
        // Approximate circle with 12-segment fan
        const segments = 12;
        const tris: number[][] = [];
        const r = Math.max(hw, hh);
        for (let i = 0; i < segments; i++) {
          const a0 = (i / segments) * Math.PI * 2;
          const a1 = ((i + 1) / segments) * Math.PI * 2;
          const [x0, y0] = rot(Math.cos(a0) * r, Math.sin(a0) * r);
          const [x1, y1] = rot(Math.cos(a1) * r, Math.sin(a1) * r);
          tris.push([cx, cy, x0, y0, x1, y1]);
        }
        return tris;
      }

      case 'roundrect':
      case 'oblong': {
        // Approximate with 4 corner arcs (4 segments each) + rect body
        // For simplicity and merge-efficiency, use an octagon approximation
        const cornerR = Math.min(hw, hh) * 0.25;
        const tris: number[][] = [];

        // 8 corners of the octagon
        const pts: [number, number][] = [
          rot(-hw + cornerR, -hh),
          rot(hw - cornerR, -hh),
          rot(hw, -hh + cornerR),
          rot(hw, hh - cornerR),
          rot(hw - cornerR, hh),
          rot(-hw + cornerR, hh),
          rot(-hw, hh - cornerR),
          rot(-hw, -hh + cornerR),
        ];

        // Fan triangulation from center
        for (let i = 0; i < pts.length; i++) {
          const [x0, y0] = pts[i];
          const [x1, y1] = pts[(i + 1) % pts.length];
          tris.push([cx, cy, x0, y0, x1, y1]);
        }
        return tris;
      }

      case 'rect':
      default: {
        // Two triangles for a rectangle
        const [tl0, tl1] = rot(-hw, -hh);
        const [tr0, tr1] = rot(hw, -hh);
        const [br0, br1] = rot(hw, hh);
        const [bl0, bl1] = rot(-hw, hh);
        return [
          [tl0, tl1, tr0, tr1, br0, br1],
          [tl0, tl1, br0, br1, bl0, bl1],
        ];
      }
    }
  }

  /**
   * Build via geometry using InstancedMesh for efficiency.
   * Vias are cylinders spanning full board thickness with a tube geometry (drilled hole).
   */
  private buildVias(vias: ViaInfo[], viaGroup: THREE.Group): void {
    if (vias.length === 0) {
      console.log('[3D] Built 0 vias (instanced)');
      return;
    }

    // Use tube geometry (cylinder with inner hole) for via annular ring
    // Template: outer_diameter, board thickness height, 16 radial segments
    const firstVia = vias[0];
    const outerR = (firstVia.outer_diameter * NM_TO_MM) / 2;
    const innerR = (firstVia.drill * NM_TO_MM) / 2;

    // For vias with varying sizes, use the most common size as template
    // For simplicity, use a single tube geometry and per-instance scale
    const tubeGeo = new THREE.CylinderGeometry(outerR, outerR, BOARD_THICKNESS_MM, 16, 1, false);
    // CylinderGeometry is Y-up by default; rotate to Z-up
    tubeGeo.rotateX(Math.PI / 2);

    const viaMat = new THREE.MeshStandardMaterial({
      color: hexToColor(LAYER_COLORS.via),
      metalness: 0.7,
      roughness: 0.3,
    });

    const instancedMesh = new THREE.InstancedMesh(tubeGeo, viaMat, vias.length);
    instancedMesh.name = 'vias';

    const drillGeo = new THREE.CylinderGeometry(innerR, innerR, BOARD_THICKNESS_MM + 0.02, 16, 1, false);
    drillGeo.rotateX(Math.PI / 2);

    const drillMat = new THREE.MeshStandardMaterial({
      color: PCB_GREEN,
      roughness: PCB_ROUGHNESS,
    });

    const drillInstancedMesh = new THREE.InstancedMesh(drillGeo, drillMat, vias.length);
    drillInstancedMesh.name = 'via-drills';

    const matrix = new THREE.Matrix4();
    const refOuterR = outerR;
    const refInnerR = innerR;

    for (let i = 0; i < vias.length; i++) {
      const via = vias[i];
      const x = via.x * NM_TO_MM;
      const y = via.y * NM_TO_MM;
      const z = BOARD_THICKNESS_MM / 2; // center of board

      // Scale factor relative to reference via
      const thisOuterR = (via.outer_diameter * NM_TO_MM) / 2;
      const thisInnerR = (via.drill * NM_TO_MM) / 2;
      const outerScale = refOuterR > 0 ? thisOuterR / refOuterR : 1;
      const innerScale = refInnerR > 0 ? thisInnerR / refInnerR : 1;

      // Outer annular ring
      matrix.makeScale(outerScale, outerScale, 1);
      matrix.setPosition(x, y, z);
      instancedMesh.setMatrixAt(i, matrix);

      // Drill hole (slightly taller to punch through)
      matrix.makeScale(innerScale, innerScale, 1);
      matrix.setPosition(x, y, z);
      drillInstancedMesh.setMatrixAt(i, matrix);
    }

    instancedMesh.instanceMatrix.needsUpdate = true;
    drillInstancedMesh.instanceMatrix.needsUpdate = true;

    viaGroup.add(instancedMesh);
    viaGroup.add(drillInstancedMesh);

    console.log(`[3D] Built ${vias.length} vias (instanced)`);
  }

  // -- Private --

  private setBackgroundFromCSS(): void {
    const style = getComputedStyle(document.documentElement);
    const bgColor = style.getPropertyValue('--bg-canvas').trim() || '#1a1a2e';
    this.setBackground(bgColor);
  }

  private animate = (): void => {
    if (!this.active) return;
    this.animFrameId = requestAnimationFrame(this.animate);

    if (this.controls) {
      this.controls.update();
    }

    if (this.renderer && this.scene && this.camera) {
      this.renderer.render(this.scene, this.camera);
    }
  };

  private onResize(): void {
    if (!this.container || !this.renderer || !this.camera) return;

    const w = this.container.clientWidth;
    const h = this.container.clientHeight;

    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h);
  }

  private clearBoardGroup(): void {
    if (!this.boardGroup) return;

    this.boardGroup.traverse((obj) => {
      if (obj instanceof THREE.InstancedMesh || obj instanceof THREE.Mesh) {
        obj.geometry?.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach(m => m.dispose());
          } else {
            (obj.material as THREE.Material).dispose();
          }
        }
      }
    });

    while (this.boardGroup.children.length > 0) {
      this.boardGroup.remove(this.boardGroup.children[0]);
    }
  }

  private getMeshCount(): number {
    let count = 0;
    if (this.scene) {
      this.scene.traverse((obj) => {
        if (obj instanceof THREE.Mesh || obj instanceof THREE.InstancedMesh) count++;
      });
    }
    return count;
  }

  private getDrawCallCount(): number {
    if (this.renderer) {
      return this.renderer.info.render.calls;
    }
    return 0;
  }

  private updateDebugSurface(): void {
    const self = this;

    (window as any).__renderer3d = {
      get isActive() { return self.active; },
      get meshCount() { return self.getMeshCount(); },
      get drawCalls() { return self.getDrawCallCount(); },
    };
  }
}

//! CodeYourPCB WASM Rendering Bridge
//!
//! This crate provides the interface for the CodeYourPCB web viewer.
//! It bridges Rust board data to JavaScript, enabling the web UI to:
//!
//! - Load and parse `.cypcb` source files (native mode)
//! - Load pre-parsed JSON snapshots (WASM mode)
//! - Retrieve structured board snapshots for rendering
//! - Query components at specific coordinates
//!
//! # Feature Flags
//!
//! - `native` (default): Full parsing support with tree-sitter
//! - `wasm`: WASM-compatible build without tree-sitter (parsing done in JavaScript)
//!
//! # Architecture
//!
//! The rendering happens in JavaScript/Canvas - this crate only provides data.
//! The `PcbEngine` struct maintains the board state and provides query methods.
//!
//! In native mode, `load_source()` parses the .cypcb source directly.
//! In WASM mode, `load_snapshot()` receives pre-parsed JSON from JavaScript.

mod snapshot;

pub use snapshot::*;

use cypcb_core::{Nm, Point};
use cypcb_drc::{run_drc, DesignRules, DrcViolation};
use cypcb_world::footprint::FootprintLibrary;
use cypcb_world::{
    BoardWorld, Entity, FootprintRef, Layer, NetConnections, NetId, PadShape, PinConnection,
    Position, RefDes, Rotation, Value,
    components::trace::{Trace, Via},
};

// Import sync and parse only in native mode
#[cfg(feature = "native")]
use cypcb_parser::parse;
#[cfg(feature = "native")]
use cypcb_world::sync_ast_to_world;

// WASM-specific imports (only when targeting wasm32)
#[cfg(target_arch = "wasm32")]
use wasm_bindgen::prelude::*;

/// PCB Engine - main interface for JavaScript.
///
/// Maintains the board state and provides methods for loading source,
/// getting snapshots, and querying the board.
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
pub struct PcbEngine {
    world: BoardWorld,
    footprint_lib: FootprintLibrary,
    source: String,
    /// DRC violations from the last load.
    violations: Vec<DrcViolation>,
    /// Time taken for last DRC run in milliseconds.
    drc_duration_ms: u64,
}

// WASM-exposed methods
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
impl PcbEngine {
    /// Create a new PcbEngine instance.
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen(constructor))]
    pub fn new() -> PcbEngine {
        PcbEngine {
            world: BoardWorld::new(),
            footprint_lib: FootprintLibrary::new(),
            source: String::new(),
            violations: Vec::new(),
            drc_duration_ms: 0,
        }
    }

    /// Load a pre-parsed board snapshot (WASM mode).
    ///
    /// This method receives a BoardSnapshot that was parsed in JavaScript
    /// and populates the internal world state for queries.
    ///
    /// Returns an empty string on success, or an error message on failure.
    #[cfg(target_arch = "wasm32")]
    pub fn load_snapshot(&mut self, snapshot_js: wasm_bindgen::JsValue) -> String {
        // Deserialize the snapshot from JavaScript
        let snapshot: Result<BoardSnapshot, _> = serde_wasm_bindgen::from_value(snapshot_js);
        match snapshot {
            Ok(snap) => {
                self.populate_from_snapshot(&snap);
                // Run DRC after populating world
                self.run_drc_internal();
                String::new()
            }
            Err(e) => format!("Failed to deserialize snapshot: {}", e),
        }
    }

    /// Get a snapshot of the current board state for rendering (WASM version).
    ///
    /// Returns a JsValue that can be used directly in JavaScript.
    #[cfg(target_arch = "wasm32")]
    pub fn get_snapshot(&mut self) -> wasm_bindgen::JsValue {
        let snapshot = self.build_snapshot();
        serde_wasm_bindgen::to_value(&snapshot).unwrap_or(wasm_bindgen::JsValue::NULL)
    }

    /// Get a snapshot of the current board state for rendering (native version).
    ///
    /// Returns a JSON string for non-WASM targets.
    #[cfg(not(target_arch = "wasm32"))]
    pub fn get_snapshot(&mut self) -> String {
        let snapshot = self.build_snapshot();
        serde_json::to_string(&snapshot).unwrap_or_else(|_| "{}".to_string())
    }

    /// Query components at a specific point.
    ///
    /// Returns reference designator strings.
    pub fn query_point(&mut self, x_nm: i64, y_nm: i64) -> Vec<String> {
        let point: Point = Point::new(Nm(x_nm), Nm(y_nm));
        let entities: Vec<Entity> = self.world.query_point(point);

        let mut refdes_list: Vec<String> = Vec::new();
        for entity in entities {
            let maybe_refdes: Option<&RefDes> = self.world.get::<RefDes>(entity);
            if let Some(refdes) = maybe_refdes {
                let s: String = refdes.as_str().to_string();
                refdes_list.push(s);
            }
        }

        refdes_list
    }

    // ========================================================================
    // Trace Mutation API
    // ========================================================================

    /// Add a trace to the board.
    ///
    /// Creates a Manual Trace entity with the given parameters,
    /// updates the spatial index, and returns the entity index.
    ///
    /// `segments_json` is a JSON array of `[x1, y1, x2, y2, ...]` coordinate
    /// pairs in nanometers (flat array, 4 values per segment).
    ///
    /// Returns the entity index (u32) on success, or u32::MAX on error.
    pub fn add_trace(
        &mut self,
        net_name: &str,
        layer_str: &str,
        width_nm: i64,
        segments_flat: &[i64],
    ) -> u32 {
        use cypcb_world::components::trace::{Trace as TraceComp, TraceSegment, TraceSource};

        // Parse layer
        let layer = match parse_layer(layer_str) {
            Ok(l) => l,
            Err(_) => return u32::MAX,
        };

        // Segments come as flat array: [x1, y1, x2, y2, x1, y1, x2, y2, ...]
        if segments_flat.len() < 4 || segments_flat.len() % 4 != 0 {
            return u32::MAX;
        }

        let mut segments = Vec::with_capacity(segments_flat.len() / 4);
        for chunk in segments_flat.chunks_exact(4) {
            segments.push(TraceSegment::new(
                Point::new(Nm(chunk[0]), Nm(chunk[1])),
                Point::new(Nm(chunk[2]), Nm(chunk[3])),
            ));
        }

        // Intern the net name
        let net_id = self.world.intern_net(net_name);

        let trace = TraceComp {
            segments,
            width: Nm(width_nm),
            layer,
            net_id,
            locked: false,
            source: TraceSource::Manual,
        };

        let entity = self.world.spawn_entity(trace);

        // Rebuild spatial index to include the new trace
        self.rebuild_spatial_index_full();

        entity.index()
    }

    /// Add a trace from a JSON segments string (WASM-friendly).
    ///
    /// `segments_json` is a JSON array of flat coordinates:
    /// `[x1, y1, x2, y2, x3, y3, x4, y4, ...]` (4 values per segment).
    ///
    /// Returns the entity index (u32) on success, or u32::MAX on error.
    #[cfg(target_arch = "wasm32")]
    pub fn add_trace_json(
        &mut self,
        net_name: &str,
        layer_str: &str,
        width_nm: i64,
        segments_json: &str,
    ) -> u32 {
        let coords: Vec<i64> = match serde_json::from_str(segments_json) {
            Ok(v) => v,
            Err(_) => return u32::MAX,
        };
        self.add_trace(net_name, layer_str, width_nm, &coords)
    }

    /// Remove a trace by entity index.
    ///
    /// Returns `true` if the trace was found and removed, `false` otherwise.
    pub fn remove_trace(&mut self, trace_id: u32) -> bool {
        // Find the actual entity with this index among trace entities
        let entity_to_remove = self.find_trace_entity(trace_id);

        if let Some(entity) = entity_to_remove {
            self.world.ecs_mut().despawn(entity);
            self.rebuild_spatial_index_full();
            true
        } else {
            false
        }
    }

    /// Query for a trace entity at a given point with tolerance.
    ///
    /// Returns the trace entity index if found, or u32::MAX if not.
    /// Tolerance is in nanometers — the point is expanded into a
    /// query rectangle of `2*tolerance` side length.
    pub fn get_trace_at_point(&mut self, x_nm: i64, y_nm: i64, tolerance_nm: i64) -> u32 {
        use cypcb_core::Rect;
        use cypcb_world::components::trace::Trace as TraceComp;

        let query_rect = Rect::new(
            Point::new(Nm(x_nm - tolerance_nm), Nm(y_nm - tolerance_nm)),
            Point::new(Nm(x_nm + tolerance_nm), Nm(y_nm + tolerance_nm)),
        );

        let candidates = self.world.query_region(query_rect);
        let query_point = Point::new(Nm(x_nm), Nm(y_nm));

        // Find the closest trace among candidates
        let mut best_entity: Option<u32> = None;
        let mut best_dist: i64 = i64::MAX;

        for entity in candidates {
            let trace_opt: Option<&TraceComp> = self.world.get::<TraceComp>(entity);
            if let Some(trace) = trace_opt {
                // Check point-to-segment distance for each segment
                let half_width = trace.width.0 / 2;
                for seg in &trace.segments {
                    let dist = point_to_segment_distance(query_point, seg.start, seg.end);
                    // If within the copper width, it's a hit
                    if dist <= half_width + tolerance_nm && dist < best_dist {
                        best_dist = dist;
                        best_entity = Some(entity.index());
                    }
                }
            }
        }

        best_entity.unwrap_or(u32::MAX)
    }

    /// Run DRC and return violation count.
    ///
    /// This runs a full DRC check (incremental optimization deferred)
    /// and updates the internal violation list.
    pub fn run_drc_incremental(&mut self) -> usize {
        self.run_drc_internal();
        self.violations.len()
    }

    /// Get the number of trace entities in the world.
    pub fn trace_count(&mut self) -> usize {
        let ecs = self.world.ecs_mut();
        let mut query = ecs.query::<&cypcb_world::components::trace::Trace>();
        query.iter(ecs).count()
    }

    /// Get DRC violations as JSON string (WASM-friendly).
    #[cfg(target_arch = "wasm32")]
    pub fn get_violations_json(&self) -> String {
        let violations: Vec<ViolationInfo> = self
            .violations
            .iter()
            .map(ViolationInfo::from_drc)
            .collect();
        serde_json::to_string(&violations).unwrap_or_else(|_| "[]".to_string())
    }

    /// Get DRC violations as JSON string (native).
    #[cfg(not(target_arch = "wasm32"))]
    pub fn get_violations_json(&self) -> String {
        let violations: Vec<ViolationInfo> = self
            .violations
            .iter()
            .map(ViolationInfo::from_drc)
            .collect();
        serde_json::to_string(&violations).unwrap_or_else(|_| "[]".to_string())
    }
}

// Internal methods (not exposed to WASM)
impl PcbEngine {
    /// Load and parse source code (native mode only).
    ///
    /// Returns an empty string on success, or an error message on failure.
    /// The board state is updated even if there are errors (partial results).
    /// DRC is run automatically after successful sync.
    ///
    /// In WASM mode, use `load_snapshot()` instead.
    #[cfg(feature = "native")]
    pub fn load_source(&mut self, source: &str) -> String {
        self.source = source.to_string();
        self.world.clear();
        self.violations.clear();
        self.drc_duration_ms = 0;

        // Parse the source
        let parse_result = parse(source);

        // Collect parse errors
        let mut errors: Vec<String> = Vec::new();
        for e in &parse_result.errors {
            errors.push(format!("{}", e));
        }

        // Sync AST to world
        let sync_result =
            sync_ast_to_world(&parse_result.value, source, &mut self.world, &self.footprint_lib);

        // Collect sync errors
        for err in &sync_result.errors {
            errors.push(format!("{}", err));
        }

        // Run DRC after sync (even if there were parse/sync errors, check what we have)
        self.run_drc_internal();

        if errors.is_empty() {
            String::new()
        } else {
            errors.join("\n")
        }
    }

    /// Run DRC using default rules (JLCPCB 2-layer).
    fn run_drc_internal(&mut self) {
        let rules = DesignRules::default();
        let result = run_drc(&mut self.world, &rules);
        self.violations = result.violations;
        self.drc_duration_ms = result.duration_ms;
    }

    /// Load routes from a .routes file content string.
    ///
    /// This parses the routes file format and adds Trace/Via entities
    /// to the world. Existing autorouted traces are cleared first.
    ///
    /// Returns an empty string on success, or error message on failure.
    #[cfg(feature = "native")]
    pub fn load_routes(&mut self, routes_content: &str) -> String {
        let mut errors: Vec<String> = Vec::new();

        // Clear existing autorouted traces and vias
        self.clear_autorouted_traces();

        // Parse routes file
        for line in routes_content.lines() {
            let line = line.trim();

            // Skip comments and empty lines
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // Parse segment: net_id layer width_nm x1 y1 x2 y2
            if line.starts_with("segment ") {
                if let Err(e) = self.parse_route_segment(line) {
                    errors.push(format!("Invalid segment: {} - {}", line, e));
                }
            }
            // Parse via: net_id x y drill_nm start_layer end_layer
            else if line.starts_with("via ") {
                if let Err(e) = self.parse_route_via(line) {
                    errors.push(format!("Invalid via: {} - {}", line, e));
                }
            }
            // Skip other lines (version, metrics, etc.)
        }

        // Rebuild spatial index to include newly loaded traces/vias
        self.rebuild_spatial_index_full();

        if errors.is_empty() {
            String::new()
        } else {
            errors.join("\n")
        }
    }

    /// Rebuild the spatial index including components, traces, and vias.
    fn rebuild_spatial_index_full(&mut self) {
        let lib = &self.footprint_lib;
        self.world.rebuild_spatial_index_with_traces(|name| {
            lib.get(name)
                .map(|fp| fp.courtyard)
                .unwrap_or_else(|| {
                    cypcb_core::Rect::from_center_size(
                        Point::ORIGIN,
                        (Nm::from_mm(1.0), Nm::from_mm(1.0)),
                    )
                })
        });
    }

    /// Clear autorouted traces and vias from the world.
    fn clear_autorouted_traces(&mut self) {
        use cypcb_world::components::trace::{Trace, TraceSource, Via};

        // Collect entities to remove
        let entities_to_remove: Vec<Entity> = {
            let ecs = self.world.ecs_mut();
            let mut trace_query = ecs.query::<(Entity, &Trace)>();
            let trace_entities: Vec<Entity> = trace_query
                .iter(ecs)
                .filter(|(_, trace)| trace.source == TraceSource::Autorouted && !trace.locked)
                .map(|(entity, _)| entity)
                .collect();
            trace_entities
        };

        let via_entities_to_remove: Vec<Entity> = {
            let ecs = self.world.ecs_mut();
            let mut via_query = ecs.query::<(Entity, &Via)>();
            let via_entities: Vec<Entity> = via_query
                .iter(ecs)
                .filter(|(_, via)| !via.locked)
                .map(|(entity, _)| entity)
                .collect();
            via_entities
        };

        // Remove entities
        let ecs = self.world.ecs_mut();
        for entity in entities_to_remove {
            ecs.despawn(entity);
        }
        for entity in via_entities_to_remove {
            ecs.despawn(entity);
        }
    }

    /// Parse a segment line from routes file.
    #[cfg(feature = "native")]
    fn parse_route_segment(&mut self, line: &str) -> Result<(), String> {
        use cypcb_world::components::trace::{Trace, TraceSegment, TraceSource};

        // segment net_id layer width_nm x1 y1 x2 y2
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 8 {
            return Err(format!("expected 8 parts, got {}", parts.len()));
        }

        let net_id_num: u32 = parts[1].parse().map_err(|e| format!("net_id: {}", e))?;
        let layer_str = parts[2];
        let width: i64 = parts[3].parse().map_err(|e| format!("width: {}", e))?;
        let x1: i64 = parts[4].parse().map_err(|e| format!("x1: {}", e))?;
        let y1: i64 = parts[5].parse().map_err(|e| format!("y1: {}", e))?;
        let x2: i64 = parts[6].parse().map_err(|e| format!("x2: {}", e))?;
        let y2: i64 = parts[7].parse().map_err(|e| format!("y2: {}", e))?;

        // Parse layer
        let layer = parse_layer(layer_str)?;

        // Create trace
        let trace = Trace {
            segments: vec![TraceSegment::new(
                Point::new(Nm(x1), Nm(y1)),
                Point::new(Nm(x2), Nm(y2)),
            )],
            width: Nm(width),
            layer,
            net_id: NetId::new(net_id_num),
            locked: false,
            source: TraceSource::Autorouted,
        };

        self.world.spawn_entity(trace);
        Ok(())
    }

    /// Parse a via line from routes file.
    #[cfg(feature = "native")]
    fn parse_route_via(&mut self, line: &str) -> Result<(), String> {
        use cypcb_world::components::trace::Via;

        // via net_id x y drill_nm start_layer end_layer
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 7 {
            return Err(format!("expected 7 parts, got {}", parts.len()));
        }

        let net_id_num: u32 = parts[1].parse().map_err(|e| format!("net_id: {}", e))?;
        let x: i64 = parts[2].parse().map_err(|e| format!("x: {}", e))?;
        let y: i64 = parts[3].parse().map_err(|e| format!("y: {}", e))?;
        let drill: i64 = parts[4].parse().map_err(|e| format!("drill: {}", e))?;
        let start_layer_str = parts[5];
        let end_layer_str = parts[6];

        let start_layer = parse_layer(start_layer_str)?;
        let end_layer = parse_layer(end_layer_str)?;

        let via = Via {
            position: Point::new(Nm(x), Nm(y)),
            drill: Nm(drill),
            outer_diameter: Nm(drill * 2), // Default annular ring
            start_layer,
            end_layer,
            net_id: NetId::new(net_id_num),
            locked: false,
        };

        self.world.spawn_entity(via);
        Ok(())
    }

    /// Find a trace entity by its index.
    ///
    /// Searches all trace entities and returns the one whose entity index
    /// matches the given id. This is needed because `Entity::from_raw(id)`
    /// may not match the actual generation of the entity.
    fn find_trace_entity(&mut self, trace_id: u32) -> Option<Entity> {
        let ecs = self.world.ecs_mut();
        let mut query = ecs.query::<(Entity, &cypcb_world::components::trace::Trace)>();
        for (entity, _) in query.iter(ecs) {
            if entity.index() == trace_id {
                return Some(entity);
            }
        }
        None
    }

    /// Get the number of DRC violations from the last load.
    pub fn violation_count(&self) -> usize {
        self.violations.len()
    }

    /// Get the time taken for the last DRC run in milliseconds.
    pub fn drc_duration_ms(&self) -> u64 {
        self.drc_duration_ms
    }

    /// Populate the world from a BoardSnapshot.
    fn populate_from_snapshot(&mut self, snapshot: &BoardSnapshot) {
        self.world.clear();
        self.violations.clear();

        // Create board entity if present
        if let Some(board) = &snapshot.board {
            self.world.set_board(
                board.name.clone(),
                (Nm(board.width_nm), Nm(board.height_nm)),
                board.layer_count,
            );
        }

        // Build map of component.pin -> net_id from snapshot.nets
        // This is needed to populate NetConnections for each component (for DRC)
        let mut pin_to_net: std::collections::HashMap<String, NetId> =
            std::collections::HashMap::new();
        for net in &snapshot.nets {
            // Intern the net name to get a NetId
            let net_id = self.world.intern_net(&net.name);
            for conn in &net.connections {
                let key = format!("{}.{}", conn.component, conn.pin);
                pin_to_net.insert(key, net_id);
            }
        }

        // Register footprints from snapshot data (needed for DRC)
        // If snapshot has pads, use those. Otherwise use builtin library.
        // Note: JS parser doesn't populate pads, so we fall back to builtin library.
        let mut registered: std::collections::HashSet<String> = std::collections::HashSet::new();
        for comp in &snapshot.components {
            if !comp.footprint.is_empty() && !registered.contains(&comp.footprint) {
                if !comp.pads.is_empty() {
                    // Use pads from snapshot (custom footprint)
                    let footprint = self.footprint_from_pads(&comp.footprint, &comp.pads);
                    self.footprint_lib.register(footprint);
                }
                // If pads are empty, the builtin library (loaded in new()) should have it
                registered.insert(comp.footprint.clone());
            }
        }

        // Create component entities with proper NetConnections
        for comp in &snapshot.components {
            let refdes = RefDes::new(&comp.refdes);
            let value = Value::new(&comp.value);
            let position = Position(Point::new(Nm(comp.x_nm), Nm(comp.y_nm)));
            let rotation = Rotation(comp.rotation_mdeg);
            let footprint_ref = FootprintRef::new(&comp.footprint);

            // Build NetConnections from pin_to_net map
            let mut nets = NetConnections::new();
            // Get pad numbers from footprint library (since JS parser may not have pads)
            if let Some(fp) = self.footprint_lib.get(&comp.footprint) {
                for pad in &fp.pads {
                    let key = format!("{}.{}", comp.refdes, pad.number);
                    if let Some(&net_id) = pin_to_net.get(&key) {
                        nets.add(PinConnection::new(&pad.number, net_id));
                    }
                }
            }

            self.world.spawn_component(refdes, value, position, rotation, footprint_ref, nets);
        }

        // Rebuild spatial index for DRC queries (includes traces and vias)
        self.rebuild_spatial_index_full();
    }

    /// Create a Footprint from PadInfo data.
    fn footprint_from_pads(&self, name: &str, pads: &[PadInfo]) -> cypcb_world::footprint::Footprint {
        use cypcb_world::footprint::{Footprint, PadDef};

        let mut pad_defs: Vec<PadDef> = Vec::with_capacity(pads.len());

        for pad in pads {
            // Convert shape string to PadShape
            let shape = match pad.shape.as_str() {
                "circle" => PadShape::Circle,
                "roundrect" => PadShape::RoundRect { corner_ratio: 25 },
                "oblong" => PadShape::Oblong,
                _ => PadShape::Rect, // default to rect
            };

            // Convert layer_mask to Vec<Layer>
            let mut layers: Vec<Layer> = Vec::new();
            if pad.layer_mask & 1 != 0 {
                layers.push(Layer::TopCopper);
            }
            if pad.layer_mask & 2 != 0 {
                layers.push(Layer::BottomCopper);
            }
            for i in 0..30 {
                if pad.layer_mask & (1 << (2 + i)) != 0 {
                    layers.push(Layer::Inner(i));
                }
            }
            // If no layers specified, default to top copper
            if layers.is_empty() {
                layers.push(Layer::TopCopper);
            }

            pad_defs.push(PadDef {
                number: pad.number.clone(),
                shape,
                position: Point::new(Nm(pad.x_nm), Nm(pad.y_nm)),
                size: (Nm(pad.width_nm), Nm(pad.height_nm)),
                drill: pad.drill_nm.map(Nm),
                layers,
            });
        }

        // Calculate bounds from pads
        let mut min_x = i64::MAX;
        let mut min_y = i64::MAX;
        let mut max_x = i64::MIN;
        let mut max_y = i64::MIN;

        for pad in &pad_defs {
            let half_w = pad.size.0.0 / 2;
            let half_h = pad.size.1.0 / 2;
            min_x = min_x.min(pad.position.x.0 - half_w);
            min_y = min_y.min(pad.position.y.0 - half_h);
            max_x = max_x.max(pad.position.x.0 + half_w);
            max_y = max_y.max(pad.position.y.0 + half_h);
        }

        use cypcb_core::Rect;
        let bounds = if min_x <= max_x && min_y <= max_y {
            Rect::new(Point::new(Nm(min_x), Nm(min_y)), Point::new(Nm(max_x), Nm(max_y)))
        } else {
            Rect::new(Point::new(Nm(0), Nm(0)), Point::new(Nm(0), Nm(0)))
        };

        // Courtyard is bounds with margin
        let margin = Nm(250_000); // 0.25mm margin
        let courtyard = Rect::new(
            Point::new(Nm(min_x - margin.0), Nm(min_y - margin.0)),
            Point::new(Nm(max_x + margin.0), Nm(max_y + margin.0)),
        );

        Footprint {
            name: name.to_string(),
            description: format!("Reconstructed from snapshot: {}", name),
            pads: pad_defs,
            bounds,
            courtyard,
        }
    }

    /// Build a BoardSnapshot from the current world state.
    pub fn build_snapshot(&mut self) -> BoardSnapshot {
        // Build board info
        let board: Option<BoardInfo> = match self.world.board_info() {
            Some((size, layers)) => {
                let name: String = self.world.board_name().unwrap_or("").to_string();
                Some(BoardInfo {
                    name,
                    width_nm: size.width.0,
                    height_nm: size.height.0,
                    layer_count: layers.count,
                })
            }
            None => None,
        };

        // Build component info
        let component_data: Vec<(Entity, RefDes, Position)> = self.world.components();
        let mut components: Vec<ComponentInfo> = Vec::with_capacity(component_data.len());

        for tuple in component_data {
            let entity: Entity = tuple.0;
            let refdes: RefDes = tuple.1;
            let position: Position = tuple.2;

            // Get value
            let value: String = match self.world.get::<Value>(entity) {
                Some(v) => v.as_str().to_string(),
                None => String::new(),
            };

            // Get rotation
            let rotation: i32 = match self.world.get::<Rotation>(entity) {
                Some(r) => r.0,
                None => 0,
            };

            // Get footprint name
            let footprint_name: String = match self.world.get::<FootprintRef>(entity) {
                Some(f) => f.as_str().to_string(),
                None => String::new(),
            };

            // Get pad info from footprint library
            let mut pads: Vec<PadInfo> = Vec::new();
            if let Some(fp) = self.footprint_lib.get(&footprint_name) {
                for pad in &fp.pads {
                    let mut layer_mask: u32 = 0;
                    for layer in &pad.layers {
                        let layer: &Layer = layer;
                        layer_mask |= layer.to_copper_mask();
                    }
                    let drill_nm: Option<i64> = match pad.drill {
                        Some(d) => Some(d.0),
                        None => None,
                    };
                    pads.push(PadInfo {
                        number: pad.number.clone(),
                        x_nm: pad.position.x.0,
                        y_nm: pad.position.y.0,
                        width_nm: pad.size.0.0,
                        height_nm: pad.size.1.0,
                        shape: pad_shape_to_string(&pad.shape),
                        layer_mask,
                        drill_nm,
                    });
                }
            }

            let refdes_str: String = refdes.as_str().to_string();
            components.push(ComponentInfo {
                refdes: refdes_str,
                value,
                x_nm: position.0.x.0,
                y_nm: position.0.y.0,
                rotation_mdeg: rotation,
                footprint: footprint_name,
                pads,
            });
        }

        // Build net info - collect nets first to avoid borrow issues
        let mut net_list: Vec<(NetId, String)> = Vec::new();
        for pair in self.world.nets() {
            let id: NetId = pair.0;
            let name: &str = pair.1;
            net_list.push((id, name.to_string()));
        }

        let mut nets: Vec<NetInfo> = Vec::with_capacity(net_list.len());

        for (net_id, net_name) in net_list {
            // Find all connections to this net
            let mut connections: Vec<PinRef> = Vec::new();

            let components_for_net: Vec<(Entity, RefDes, Position)> = self.world.components();
            for tuple in components_for_net {
                let entity: Entity = tuple.0;
                let refdes: RefDes = tuple.1;

                let net_conns_opt: Option<&NetConnections> =
                    self.world.get::<NetConnections>(entity);
                if let Some(net_conns) = net_conns_opt {
                    for conn in net_conns.iter() {
                        let conn: &PinConnection = conn;
                        if conn.net == net_id {
                            let comp_str: String = refdes.as_str().to_string();
                            connections.push(PinRef {
                                component: comp_str,
                                pin: conn.pin.clone(),
                            });
                        }
                    }
                }
            }

            nets.push(NetInfo {
                name: net_name,
                id: net_id.0,
                connections,
            });
        }

        // Build violations info
        let violations: Vec<ViolationInfo> = self
            .violations
            .iter()
            .map(ViolationInfo::from_drc)
            .collect();

        // Build trace info
        let traces = self.collect_traces();

        // Build via info
        let vias = self.collect_vias();

        // Build ratsnest info (unrouted connections)
        let ratsnest = self.collect_ratsnest(&nets);

        BoardSnapshot {
            board,
            components,
            nets,
            violations,
            traces,
            vias,
            ratsnest,
        }
    }

    /// Collect all traces from the world.
    fn collect_traces(&mut self) -> Vec<TraceInfo> {
        // Collect trace data with entity IDs (cloning to avoid borrow issues)
        let trace_data: Vec<(u32, Trace)> = {
            let world_ref = self.world.ecs_mut();
            let mut query = world_ref.query::<(Entity, &Trace)>();
            query.iter(world_ref).map(|(e, t)| (e.index(), t.clone())).collect()
        };

        // Now process with net names
        let mut traces: Vec<TraceInfo> = Vec::new();
        for (entity_id, trace) in trace_data {
            let layer_name = match trace.layer {
                Layer::TopCopper => "Top".to_string(),
                Layer::BottomCopper => "Bottom".to_string(),
                Layer::Inner(n) => format!("Inner{}", n),
                _ => "Top".to_string(),
            };

            let net_name = self.world.net_name(trace.net_id)
                .unwrap_or("(no net)")
                .to_string();

            let segments: Vec<TraceSegmentInfo> = trace.segments.iter().map(|seg| {
                TraceSegmentInfo {
                    start_x: seg.start.x.0 as f64,
                    start_y: seg.start.y.0 as f64,
                    end_x: seg.end.x.0 as f64,
                    end_y: seg.end.y.0 as f64,
                }
            }).collect();

            traces.push(TraceInfo {
                id: entity_id,
                segments,
                width: trace.width.0 as f64,
                layer: layer_name,
                net_name,
                locked: trace.locked,
            });
        }

        traces
    }

    /// Collect all vias from the world.
    fn collect_vias(&mut self) -> Vec<ViaInfo> {
        // Collect via data with entity IDs (copying to avoid borrow issues)
        let via_data: Vec<(u32, Via)> = {
            let world_ref = self.world.ecs_mut();
            let mut query = world_ref.query::<(Entity, &Via)>();
            query.iter(world_ref).map(|(e, v)| (e.index(), *v)).collect()
        };

        // Now process with net names
        let mut vias: Vec<ViaInfo> = Vec::new();
        for (entity_id, via) in via_data {
            let net_name = self.world.net_name(via.net_id)
                .unwrap_or("(no net)")
                .to_string();

            vias.push(ViaInfo {
                id: entity_id,
                x: via.position.x.0 as f64,
                y: via.position.y.0 as f64,
                drill: via.drill.0 as f64,
                outer_diameter: via.outer_diameter.0 as f64,
                net_name,
            });
        }

        vias
    }

    /// Calculate ratsnest (unrouted connections).
    ///
    /// For each net with multiple pins, if there are no traces connecting
    /// all pins, we show ratsnest lines between unconnected pin pairs.
    ///
    /// Simple algorithm: For nets with pins but no traces, show lines
    /// from first pin to all other pins (star topology for visualization).
    fn collect_ratsnest(&mut self, nets: &[NetInfo]) -> Vec<RatsnestInfo> {
        use std::collections::HashMap;

        let mut ratsnest: Vec<RatsnestInfo> = Vec::new();

        // Get trace count per net to determine if net is routed
        let mut traces_per_net: HashMap<String, usize> = HashMap::new();
        for trace in self.collect_traces() {
            *traces_per_net.entry(trace.net_name.clone()).or_insert(0) += 1;
        }

        // For each net with connections
        for net in nets {
            if net.connections.len() < 2 {
                continue; // Need at least 2 pins to show ratsnest
            }

            // If net has traces, assume it's at least partially routed
            // (A full ratsnest would check actual connectivity, but this is MVP)
            if traces_per_net.contains_key(&net.name) {
                continue;
            }

            // Get pin positions
            let mut pin_positions: Vec<(f64, f64)> = Vec::new();

            for conn in &net.connections {
                // Find the component
                if let Some(entity) = self.world.find_by_refdes(&conn.component) {
                    if let Some(pos) = self.world.get::<Position>(entity) {
                        // Get the pad offset from footprint
                        let footprint_name = self.world.get::<FootprintRef>(entity)
                            .map(|f| f.as_str().to_string())
                            .unwrap_or_default();

                        let pad_offset = self.get_pad_offset(&footprint_name, &conn.pin);
                        let rotation = self.world.get::<Rotation>(entity)
                            .map(|r| r.0)
                            .unwrap_or(0);

                        // Apply rotation to pad offset
                        let radians = (rotation as f64 / 1000.0) * (std::f64::consts::PI / 180.0);
                        let cos = radians.cos();
                        let sin = radians.sin();

                        let rotated_x = pad_offset.0 * cos - pad_offset.1 * sin;
                        let rotated_y = pad_offset.0 * sin + pad_offset.1 * cos;

                        let pin_x = pos.0.x.0 as f64 + rotated_x;
                        let pin_y = pos.0.y.0 as f64 + rotated_y;

                        pin_positions.push((pin_x, pin_y));
                    }
                }
            }

            // Create star-topology ratsnest from first pin to all others
            if pin_positions.len() >= 2 {
                let (first_x, first_y) = pin_positions[0];
                for (x, y) in pin_positions.iter().skip(1) {
                    ratsnest.push(RatsnestInfo {
                        start_x: first_x,
                        start_y: first_y,
                        end_x: *x,
                        end_y: *y,
                        net_name: net.name.clone(),
                    });
                }
            }
        }

        ratsnest
    }

    /// Get pad offset from component origin for a given footprint and pin.
    fn get_pad_offset(&self, footprint_name: &str, pin: &str) -> (f64, f64) {
        if let Some(fp) = self.footprint_lib.get(footprint_name) {
            for pad in &fp.pads {
                if pad.number == pin {
                    return (pad.position.x.0 as f64, pad.position.y.0 as f64);
                }
            }
        }
        // Default to origin if pad not found
        (0.0, 0.0)
    }
}

impl Default for PcbEngine {
    fn default() -> Self {
        Self::new()
    }
}

/// Compute the shortest distance from a point to a line segment.
///
/// Returns the perpendicular distance if the projection falls on the segment,
/// otherwise the distance to the nearest endpoint.
fn point_to_segment_distance(p: Point, a: Point, b: Point) -> i64 {
    let dx = b.x.0 - a.x.0;
    let dy = b.y.0 - a.y.0;
    let len_sq = (dx as i128) * (dx as i128) + (dy as i128) * (dy as i128);

    if len_sq == 0 {
        // Degenerate segment (a == b), distance to point
        let ex = (p.x.0 - a.x.0) as i128;
        let ey = (p.y.0 - a.y.0) as i128;
        return ((ex * ex + ey * ey) as f64).sqrt() as i64;
    }

    // Project p onto line ab, compute parameter t
    let apx = (p.x.0 - a.x.0) as i128;
    let apy = (p.y.0 - a.y.0) as i128;
    let dot = apx * (dx as i128) + apy * (dy as i128);

    // Clamp t to [0, 1]
    let t = (dot as f64) / (len_sq as f64);
    let t = t.clamp(0.0, 1.0);

    // Closest point on segment
    let cx = a.x.0 as f64 + t * dx as f64;
    let cy = a.y.0 as f64 + t * dy as f64;

    let ex = p.x.0 as f64 - cx;
    let ey = p.y.0 as f64 - cy;

    (ex * ex + ey * ey).sqrt() as i64
}

/// Convert PadShape enum to string for JS serialization.
fn pad_shape_to_string(shape: &PadShape) -> String {
    match shape {
        PadShape::Circle => "circle".to_string(),
        PadShape::Rect => "rect".to_string(),
        PadShape::RoundRect { .. } => "roundrect".to_string(),
        PadShape::Oblong => "oblong".to_string(),
    }
}

/// Parse layer string from routes file format.
fn parse_layer(layer_str: &str) -> Result<Layer, String> {
    match layer_str {
        "TopCopper" | "Top" => Ok(Layer::TopCopper),
        "BottomCopper" | "Bottom" => Ok(Layer::BottomCopper),
        _ if layer_str.starts_with("Inner(") && layer_str.ends_with(")") => {
            let inner = &layer_str[6..layer_str.len() - 1];
            let num: u8 = inner.parse().map_err(|e| format!("Invalid inner layer: {}", e))?;
            Ok(Layer::Inner(num))
        }
        _ if layer_str.starts_with("Inner") => {
            let num_str = &layer_str[5..];
            let num: u8 = num_str.parse().map_err(|e| format!("Invalid inner layer: {}", e))?;
            Ok(Layer::Inner(num))
        }
        _ => Err(format!("Unknown layer: {}", layer_str)),
    }
}

